   "summary": "金融街论坛年会上央行宣布，支持北京、上海、粤港澳大湾区打造国际级创投中心，将高研发投入民营中小企纳入科技创新再贷款；推出应对非银机构大额赎回的流动性支持工具，扩大SLF适用机构，推动银行间与交易所债市互联互通。",
