   "summary": "潘功胜明确，央行将研究择机把公开市场主要操作品种期限切换为隔夜，使隔夜回购利率成为主要政策利率，推动贷款利率定价基准多元化并退出存贷款基准利率，稳妥推进AI在金融领域应用。",
