   "summary": "证监会按'违规转让比例+金额'双指标精准划分裁量阶次：违规比例不足2%或金额不足4000万元的从轻处罚；比例5%以上且金额5亿元以上从重。明确十余种从轻、从重情节，封堵'马甲账户''违规代持'。",
