   "summary": "金融监管总局、央行、证监会联合发布16项金融业为民办实事举措范例，仅有6家机构入选，招联凭智鹿大模型消保智能体成为唯一上榜消金公司，也是唯一以金融大模型应用入选的金融机构。",
