   "summary": "国内EDA企业联合主流晶圆厂宣布，自主研发的全流程数字EDA工具完成28nm工艺制程全流程验证，流片良率达98.5%，主频、功耗、面积等关键指标与海外工具持平，标志国产EDA首次在成熟制程实现全流程闭环落地，半导体产业链自主可控再补核心短板。",
