   "summary": "多地流感疫苗有序接种，农村符合条件老人与学生免费，城区自愿自费；西安多区设老年优先通道、学生集中接种专场与延时服务，依托「疫苗处方」由医生同步评估推荐。",
   "decision": "秋冬流感季，开心月龄小、易感人群密集，建议咨询社区接种安排与月龄适配，做好呼吸道防护。",
