   "summary": "国家卫生健康委通知延长2022—2024年出生婴幼儿首次育儿补贴申请截止时间至2026年12月31日。对2025年及以后出生、符合条件的婴幼儿，须在出生当年或次年提出首次申领；2026年新出生婴幼儿也建议在年内完成首申，逾期不予补领。每孩每年3600元、发放至满3周岁。",
