   "summary": "南昌市东湖区开展2026年上半年普惠性托育机构婴幼儿入托补贴工作，经机构申请、区级审核，拟享受补贴机构4家，公示期10月16日至10月22日。该区落实0-3岁婴幼儿照护服务托位民生实事项目，由卫健委发放。",
   "decision": "普惠托育补贴在多地铺开，建宝家庭后续如需托育可优先选择备案普惠机构，关注当地入托补助标准。",
