   "summary": "商务部等九部门发布国内首份'科技兴商'专项政策，从科技赋能商品消费提质、服务消费扩容、商贸流通畅通、未来商业场景四方面提出18条举措，并部署'人工智能+制造''人工智能+文旅'试点。",
   "decision": "科技兴商推动商贸数字化，与招联×联通在消费场景、泛曝光合作方向一致，可关注政策红利下的场景化营销机会。",
