   "summary": "美国太空军近日首次承认电磁战武器已投入实战，成为试验场的正是美国近期直接动武的两个国家——委内瑞拉和伊朗。美空军部长称美国现已拥有在轨“太空控制武器”，可保护部队免受敌对卫星攻击，这是美国首次承认在太空具备“进攻能力”。",
