   "summary": "人社部、中央网信办、教育部、公安部、国资委日前联合发布警惕“央国企内推”等骗局风险提示，提醒求职者特别是高校毕业生提高防范意识。当前正值求职招聘旺季，不法分子冒用央国企名义发布虚假招聘、以“内部推荐”“直签保录”等幌子诱导支付高额费用，严重侵害权益。",
   "decision": "招聘骗局高发期，提醒身边应届求职亲友通过官方渠道核验，避免财产损失。",
